import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import {
  collection, query, where,
  onSnapshot, updateDoc, doc, deleteDoc,
} from 'firebase/firestore';

const EMPTY_GIF  = "data:image/gif;base64,";

const tipoIcon  = { xp_perda:'❌', xp_ganho:'⭐', nova_demanda:'📋', nova_demanda_pp:'📋', info:'ℹ️', aviso:'📢' };
const tipoColor = { xp_perda:'#e87f7f', xp_ganho:'#4caf8a', nova_demanda:'#C9A44A', nova_demanda_pp:'#6a9fd8', info:'#6a9fd8', aviso:'#C9A44A' };

export default function NotificacoesScreen({ user }) {
  const [notifs, setNotifs]   = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(
      collection(db, 'notificacoes_membros'),
      where('userId', '==', user.matricula)
    );
    const unsub = onSnapshot(q,
      snap => {
        const lista = snap.docs
          .map(d => ({ id: d.id, ...d.data() }))
          .sort((a, b) => {
            const ta = a.criadoEm?.toDate ? a.criadoEm.toDate() : new Date(a.criadoEm || 0);
            const tb = b.criadoEm?.toDate ? b.criadoEm.toDate() : new Date(b.criadoEm || 0);
            return tb - ta;
          });
        setNotifs(lista);
        setLoading(false);
        snap.docs.forEach(d => {
          if (!d.data().lida)
            updateDoc(doc(db, 'notificacoes_membros', d.id), { lida: true }).catch(()=>{});
        });
      },
      err => { console.log('Notif error:', err); setLoading(false); }
    );
    return unsub;
  }, []);

  const deletar = id => deleteDoc(doc(db, 'notificacoes_membros', id));

  const limparTodas = async () => {
    if (!window.confirm('Limpar todas?')) return;
    await Promise.all(notifs.map(n => deleteDoc(doc(db, 'notificacoes_membros', n.id))));
  };

  const formatTs = ts => {
    if (!ts?.toDate) return '';
    const diff = Date.now() - ts.toDate().getTime();
    if (diff < 60000)    return 'agora';
    if (diff < 3600000)  return Math.floor(diff/60000) + 'min';
    if (diff < 86400000) return Math.floor(diff/3600000) + 'h';
    return ts.toDate().toLocaleDateString('pt-BR', { day:'2-digit', month:'short' });
  };

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%', overflowY:'auto', paddingBottom:80 }}>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', padding:'16px 16px 12px' }}>
        <div>
          <div style={{ fontFamily:'var(--font-display)', fontSize:22, fontWeight:700, color:'var(--cream)' }}>Notificações</div>
          <div style={{ fontSize:12, color:'var(--muted)', marginTop:2 }}>{notifs.length} no total</div>
        </div>
        {notifs.length > 0 && (
          <button onClick={limparTodas}
            style={{ fontSize:12, color:'var(--muted)', background:'var(--card)', border:'1px solid var(--border)', borderRadius:10, padding:'6px 12px', fontFamily:'var(--font-body)' }}>
            Limpar tudo
          </button>
        )}
      </div>

      {loading && (
        <div style={{ display:'flex', justifyContent:'center', alignItems:'center', flex:1, padding:40 }}>
          <svg width={32} height={32} viewBox="0 0 24 24" fill="none" style={{ animation:'spin .8s linear infinite' }}>
            <circle cx="12" cy="12" r="10" stroke="var(--gold)" strokeWidth="2.5" strokeDasharray="31.4" strokeDashoffset="10" strokeLinecap="round" />
          </svg>
          <style>{'@keyframes spin { to { transform:rotate(360deg); } }'}</style>
        </div>
      )}

      {!loading && notifs.length === 0 && (
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', flex:1, padding:'32px 24px', textAlign:'center' }}>
          <img src={EMPTY_GIF} alt="Sem notificações" style={{ width:'70%', maxWidth:260, marginBottom:20, borderRadius:12 }} />
          <div style={{ fontFamily:'var(--font-display)', fontSize:18, fontWeight:700, color:'var(--cream)', marginBottom:8 }}>
            Opa, nenhuma notificação ainda!
          </div>
          <div style={{ fontSize:14, color:'var(--muted)', lineHeight:1.7 }}>Volte mais tarde.</div>
        </div>
      )}

      <div style={{ padding:'0 14px' }}>
        {notifs.map(n => {
          const cor = tipoColor[n.tipo] || 'var(--muted)';
          const ico = tipoIcon[n.tipo]  || 'ℹ️';
          return (
            <div key={n.id} style={{
              display:'flex', alignItems:'flex-start', gap:12,
              background: n.lida ? 'var(--card)' : 'rgba(201,164,74,.06)',
              border: '1px solid ' + (n.lida ? 'var(--border)' : 'rgba(201,164,74,.2)'),
              borderRadius:14, padding:'13px 14px', marginBottom:9,
            }}>
              <div style={{ width:40, height:40, borderRadius:12, background:cor+'18', border:'1px solid '+cor+'33', display:'flex', alignItems:'center', justifyContent:'center', fontSize:18, flexShrink:0 }}>
                {ico}
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:14, fontWeight:700, color:'var(--cream)', marginBottom:3 }}>{n.titulo}</div>
                <div style={{ fontSize:13, color:'var(--muted)', lineHeight:1.5 }}>{n.mensagem}</div>
                <div style={{ fontSize:11, color:'var(--muted)', marginTop:5, opacity:.6 }}>{formatTs(n.criadoEm)}</div>
              </div>
              <button onClick={() => deletar(n.id)}
                style={{ background:'none', border:'none', color:'var(--muted)', fontSize:18, lineHeight:1, flexShrink:0, opacity:.5 }}>×</button>
            </div>
          );
        })}
      </div>
    </div>
  );
}
